/** @file WebStatic.cpp @brief Embedded static asset lookup and MIME resolution. */

#ifndef NO_WEB
#include "WebInternal.h"

#include <cctype>
#include <string>

// Generated by platformio_assets.py. Paths are served from flash.
struct StaticHtmlFileEntry
{
  const char *path;
  StaticHtmlFile file;
};
extern const StaticHtmlFileEntry staticHtmlFilesLookup[];
extern const size_t staticHtmlFilesLookupCount;

struct MimeType
{
  const char *extension;
  const char *value;
};
static constexpr MimeType mimeTypes[] = {
    {".html", "text/html; charset=utf-8"},
    {".js", "application/javascript; charset=utf-8"},
    {".png", "image/png"},
    {".jpg", "image/jpeg"},
    {".ico", "image/x-icon"},
    {".css", "text/css"},
    {".svg", "image/svg+xml"},
    {".woff2", "font/woff2"},
    {".woff", "font/woff"},
    {".ttf", "font/ttf"}};

StaticHtmlFile WebInternal::getStaticHtml(const String &url)
{
  if (url == "/remote") return getStaticHtml("/vnc/index.html");
  if (url == "/remote/input") return getStaticHtml("/vnc/index.html");
  if (url.startsWith("/remote/")) return getStaticHtml(String("/vnc/") + url.substring(8));
  for (size_t i = 0; i < staticHtmlFilesLookupCount; ++i)
  {
    if (url == staticHtmlFilesLookup[i].path)
    {
      return staticHtmlFilesLookup[i].file;
    }
  }
  return {nullptr, 0, false};
}

const char *WebInternal::GetMimeType(const char *fname)
{
  std::string filename(fname);
  size_t dotPos = filename.find_last_of('.');
  if (dotPos == std::string::npos)
  {
    return nullptr;
  }

  std::string extension = filename.substr(dotPos);
  for (char &character : extension)
  {
    character = static_cast<char>(std::tolower(static_cast<unsigned char>(character)));
  }

  for (const auto &mimeType : mimeTypes)
  {
    if (extension == mimeType.extension) return mimeType.value;
  }
  return nullptr;
}

#endif
